async function useFile(f){
  file=f;if(!file)return;
  $('dl').textContent=file.name;$('go').disabled=false;buf=null;
  var lim0=pro?PROB:FREEB;
  $('m').textContent=file.size>lim0?('This file is '+(file.size/1048576).toFixed(1)+' MB, but the limit is '+Math.round(lim0/1048576)+' MB. Choose a shorter clip or an MP3.'):'';
  $('chips').classList.remove('on');$('pv').classList.remove('on');
  try{
    ctx=ctx||new (window.AudioContext||window.webkitAudioContext)();
    buf=await ctx.decodeAudioData(await file.arrayBuffer());
    $('chips').classList.add('on');$('pv').classList.add('on');syncTr();
  }catch(err){$('m').textContent='Voice effects are not available for this file, but you can still send it.';syncTr()}
}
