$('go').onclick=async function(){
  if(!file)return;
  var limit=pro?PROB:FREEB;
  if(file.size>limit){$('m').textContent='File is too big (max '+Math.round(limit/1048576)+' MB).'+(pro?'':' A Pro code allows bigger files.');return}
  var okDur=pro&&buf&&buf.duration<=60;
  var wantTR=AI&&okDur&&picked.length>0;
  var wantV=AIV&&okDur&&vsel>=0;
  if(wantTR||wantV){
    var need=1+(wantTR?AIT+AIL*picked.length:0)+(wantV?AIVC:0);
    if(credits<need){$('m').textContent='You need '+need+' credits for this. You have '+credits+'.';return}
  }
  var tok='';
  if(SITEKEY){tok=(window.turnstile&&turnstile.getResponse())||'';if(!tok){$('m').textContent='Please complete the human check first.';return}}
  $('go').disabled=true;$('m').textContent='Uploading…';
  var link='',note='';
  try{
    var body=file,type=file.type||'audio/mpeg',rateUsed=1;
    var conv=buf&&/ogg|opus|webm|amr/i.test((file.type||'')+' '+file.name);
    if(buf&&(conv||wantV||(!wantTR&&sel!=='normal'))){
      var fxn=(wantTR||wantV)?'normal':sel;rateUsed=FX[fxn].rate;
      if(buf.duration>240)throw new Error('This works for clips up to 4 minutes.');
      $('m').textContent=fxn==='normal'?'Preparing audio…':'Applying voice…';
      body=wav(await render(fxn));type='audio/wav';
      if(body.size>limit)throw new Error('Too long for this plan with a voice effect (about '+Math.floor(limit/44100)+' seconds max).'+(pro?'':' A Pro code allows longer clips.'));
      $('m').textContent='Uploading…';
    }
    var h={'content-type':type};if(pro)h['x-pro-code']=code;if(tok)h['x-turnstile']=tok;
    var r=await fetch('/api/upload?name='+encodeURIComponent(file.name)+(buf?'&wf='+peaks()+'&dur='+Math.round(buf.duration/rateUsed):''),{method:'POST',headers:h,body:body});
    var d=await r.json();if(!r.ok)throw new Error(d.error||'Upload failed');
    link=d.url;if(typeof d.credits==='number')credits=d.credits;
    if((wantTR||wantV)&&d.owner){
      var hh={'x-owner':d.owner,'x-pro-code':code};
      if(wantTR){
        try{
          $('m').textContent='Listening to your audio…';
          var r1=await fetch('/api/ai/transcribe?id='+d.id,{method:'POST',headers:hh});var j1=await r1.json();
          if(!r1.ok)throw new Error(j1.error||'Transcription failed');
          credits=j1.credits;
          var made=0,fails='';
          for(var q=0;q<picked.length;q++){
            $('m').textContent='Making '+LANGS[picked[q]]+' voice… ('+(q+1)+'/'+picked.length+')';
            var r2=await fetch('/api/ai/dub?id='+d.id+'&lang='+picked[q],{method:'POST',headers:hh});var j2=await r2.json();
            if(!r2.ok){fails+=' '+LANGS[picked[q]]+' failed: '+(j2.error||'error');continue}
            credits=j2.credits;made++;
          }
          note+=' Translated into '+made+' language'+(made===1?'':'s')+'.'+fails;
        }catch(e2){note+=' Translation failed: '+e2.message}
      }
      if(wantV){
        try{
          $('m').textContent='Changing your voice…';
          var r3=await fetch('/api/ai/voice?id='+d.id+'&voice='+vsel,{method:'POST',headers:hh});var j3=await r3.json();
          if(!r3.ok)throw new Error(j3.error||'Voice change failed');
          credits=j3.credits;note+=' Voice changed to '+j3.voice+'.';
        }catch(e3){note+=' Voice change failed: '+e3.message}
      }
    }
    $('u').value=link;$('out').style.display='block';$('m').textContent='Your link is ready ✨'+note;
    if(pro)$('pst').textContent='Pro active: '+credits+' credits left.';
  }catch(e){
    if(link){$('u').value=link;$('out').style.display='block';$('m').textContent='Your link is ready, but: '+e.message}
    else{$('m').textContent=e.message;$('go').disabled=false}
  }
  if(SITEKEY&&window.turnstile)try{turnstile.reset()}catch(e){}
};
