const isExpired = md => !!(md && md.expires && Date.parse(md.expires) < Date.now());

async function serveAudio(request, env, key) {
  const obj = await env.BUCKET.get(key, { range: request.headers });
  if (!obj || isExpired(obj.customMetadata)) return new Response('Not found', { status: 404 });
  const h = new Headers();
  obj.writeHttpMetadata(h);
  h.set('etag', obj.httpEtag);
  h.set('accept-ranges', 'bytes');
  h.set('cache-control', 'public, max-age=3600');
  let status = 200, len = obj.size;
  if (obj.range) {
    let offset = obj.range.offset ?? 0, length = obj.range.length ?? obj.size - offset;
    if (obj.range.suffix) { length = obj.range.suffix; offset = obj.size - length; }
    h.set('content-range', `bytes ${offset}-${offset + length - 1}/${obj.size}`);
    status = 206; len = length;
  }
  h.set('content-length', String(len));
  return new Response(obj.body, { status, headers: h });
}

// ---------- Upload API ----------
async function upload(request, env, url, c) {
  const ip = request.headers.get('x-nf-client-connection-ip') || request.headers.get('cf-connecting-ip') || 'unknown';

  if (env.LIMITER) {
    const { success } = await env.LIMITER.limit({ key: ip });
    if (!success) return json({ error: 'Too many uploads. Please wait a minute.' }, 429);
  }

  if (env.TURNSTILE_SECRET) {
    const fd = new FormData();
    fd.append('secret', env.TURNSTILE_SECRET);
    fd.append('response', request.headers.get('x-turnstile') || '');
    fd.append('remoteip', ip);
    const r = await fetch('https://challenges.cloudflare.com/turnstile/v0/siteverify', { method: 'POST', body: fd });
    const v = await r.json().catch(() => ({}));
    if (!v.success) return json({ error: 'Please complete the human check and try again.' }, 403);
  }

  let pro = null, code = (request.headers.get('x-pro-code') || '').trim().toUpperCase();
  if (code) {
    if (!env.DATA) return json({ error: 'Pro codes are not enabled.' }, 400);
    const raw = await env.DATA.get('c:' + code);
    pro = raw ? JSON.parse(raw) : null;
    if (!pro) return json({ error: 'That Pro code was not found.' }, 403);
    if (pro.credits <= 0) return json({ error: 'No credits left on this Pro code.' }, 402);
  }

  let dailyKey = null, dailyN = 0;
  if (!pro && env.DATA) {
    dailyKey = 'd:' + ip + ':' + new Date().toISOString().slice(0, 10);
    dailyN = Number(await env.DATA.get(dailyKey)) || 0;
    if (dailyN >= c.freeDaily) return json({ error: `Free limit reached (${c.freeDaily} uploads a day). Try tomorrow or use a Pro code.` }, 429);
  }

  const type = (request.headers.get('content-type') || '').toLowerCase();
  const body = await request.arrayBuffer();
  const size = body.byteLength;
  const maxBytes = (pro ? c.proMB : c.freeMB) * 1048576;
  if (!type.startsWith('audio/') && type !== 'video/mp4') return json({ error: 'Please upload an audio file.' }, 415);
  if (!size || size > maxBytes) return json({ error: `File is empty or larger than ${pro ? c.proMB : c.freeMB} MB.` }, 413);

  const id = newId();
  const name = (url.searchParams.get('name') || 'Audio message').replace(/\.[^.]+$/, '').slice(0, 60);
  const expires = new Date(Date.now() + (pro ? c.proDays : c.freeDays) * 864e5).toISOString();
  const owner = pro ? rnd(24, ALPHABET) : '';
  const wfRaw = url.searchParams.get('wf') || '';
  const wf = /^[0-9]{14}$/.test(wfRaw) ? wfRaw : '';
  const durN = Math.round(Number(url.searchParams.get('dur')));
  const dur = Number.isFinite(durN) && durN > 0 && durN < 7200 ? String(durN) : '';
  await env.BUCKET.put('a/' + id, body, {
    httpMetadata: { contentType: type },
    customMetadata: { title: name, created: new Date().toISOString(), expires, pro: pro ? '1' : '0', owner, wf, dur },
  });

  if (pro) { pro.credits -= 1; await env.DATA.put('c:' + code, JSON.stringify(pro)); }
  else if (dailyKey) await env.DATA.put(dailyKey, String(dailyN + 1), { expirationTtl: 172800 });

  return json({ id, url: `${url.origin}/a/${id}`, expires, credits: pro ? pro.credits : undefined, owner: owner || undefined });
}

// ---------- Stripe redeem ----------
async function redeem(url, env, c) {
  const sid = url.searchParams.get('session_id') || '';
  if (!env.STRIPE_SECRET || !env.DATA || !/^cs_[A-Za-z0-9_]+$/.test(sid)) return html(msgPage('🫥', 'Not available', 'This page needs a valid payment link.'), 400, 'no-store');
  let code = await env.DATA.get('s:' + sid);
  if (!code) {
    const r = await fetch('https://api.stripe.com/v1/checkout/sessions/' + encodeURIComponent(sid), { headers: { authorization: 'Bearer ' + env.STRIPE_SECRET } });
    const s = await r.json().catch(() => ({}));
    if (!r.ok || s.payment_status !== 'paid') return html(msgPage('⏳', 'Payment not confirmed', 'If you just paid, wait a moment and refresh this page.'), 402, 'no-store');
    code = newCode();
    await env.DATA.put('c:' + code, JSON.stringify({ credits: c.packCredits, created: new Date().toISOString() }));
    await env.DATA.put('s:' + sid, code);
  }
  return html(head('Your Pro code') + `<div class="c"><div class="big">🎉</div><h1>Thank you!</h1>
<p>Save this code. Enter it on the home page under “Have a Pro code?”</p>
<input type="text" id="k" readonly value="${esc(code)}"><button class="btn" id="b">Copy code</button>
<a class="btn" href="/">Go to home page</a></div>
<script>document.getElementById('b').onclick=function(){var k=document.getElementById('k');navigator.clipboard.writeText(k.value).then(function(){k.value='Copied! '+k.value}).catch(function(){k.select()})}</script></body></html>`, 200, 'no-store');
}

// ---------- AI: transcribe + translate + speak (client-driven steps, Pro only) ----------
const EXT = { 'audio/mpeg': 'mp3', 'audio/mp3': 'mp3', 'audio/mp4': 'm4a', 'audio/x-m4a': 'm4a', 'audio/m4a': 'm4a', 'video/mp4': 'm4a', 'audio/wav': 'wav', 'audio/x-wav': 'wav', 'audio/webm': 'webm', 'audio/ogg': 'ogg', 'audio/flac': 'flac' };
const oai = (env, path, init) => fetch('https://api.openai.com/v1/' + path, { ...init, headers: { authorization: 'Bearer ' + env.OPENAI_API_KEY, ...(init.headers || {}) } });
const errMsg = async (r, fallback) => { const j = await r.json().catch(() => ({})); return (j.error && j.error.message) || fallback; };

async function aiAuth(request, env, url, keyName = 'OPENAI_API_KEY') {
  if (!env[keyName] || !env.DATA) return { err: json({ error: 'AI features are not enabled.' }, 503) };
  const id = url.searchParams.get('id') || '';
  if (!/^[a-z0-9]{8}$/.test(id)) return { err: json({ error: 'Bad id.' }, 400) };
  const code = (request.headers.get('x-pro-code') || '').trim().toUpperCase();
  const owner = request.headers.get('x-owner') || '';
  const meta = await env.BUCKET.head('a/' + id);
  const md = meta && meta.customMetadata;
  if (!code || !md || !md.owner || md.owner !== owner || isExpired(md)) return { err: json({ error: 'Not allowed.' }, 403) };
  return { id, code, md };
}
async function charge(env, code, n) {
  const raw = await env.DATA.get('c:' + code);
  if (!raw) return { ok: false, status: 403, error: 'That Pro code was not found.' };
  const p = JSON.parse(raw);
  if (p.credits < n) return { ok: false, status: 402, error: `Not enough credits (need ${n}).` };
  p.credits -= n;
  await env.DATA.put('c:' + code, JSON.stringify(p));
  return { ok: true, left: p.credits };
}
async function refund(env, code, n) {
  const raw = await env.DATA.get('c:' + code);
  if (!raw) return;
  const p = JSON.parse(raw); p.credits += n;
  await env.DATA.put('c:' + code, JSON.stringify(p));
}

async function aiTranscribe(request, env, url, c) {
  const a = await aiAuth(request, env, url); if (a.err) return a.err;
  if (await env.BUCKET.head('t/' + a.id)) return json({ error: 'Already transcribed.' }, 409);
  const pay = await charge(env, a.code, c.aiT);
  if (!pay.ok) return json({ error: pay.error }, pay.status);
  try {
    const obj = await env.BUCKET.get('a/' + a.id);
    if (!obj) throw new Error('Audio not found.');
    if (obj.size > c.aiMaxMB * 1048576) throw new Error(`Audio is too big for translation (max ${c.aiMaxMB} MB).`);
    const ab = await new Response(obj.body).arrayBuffer();
    const ct = ((obj.httpMetadata && obj.httpMetadata.contentType) || 'audio/mpeg').toLowerCase();
    const fd = new FormData();
    fd.append('file', new Blob([ab], { type: ct }), 'audio.' + (EXT[ct] || 'mp3'));
    fd.append('model', env.STT_MODEL || 'whisper-1');
    fd.append('response_format', 'verbose_json');
    const r = await oai(env, 'audio/transcriptions', { method: 'POST', body: fd });
    if (!r.ok) throw new Error(await errMsg(r, 'Transcription failed.'));
    const j = await r.json();
    if (j.duration && j.duration > c.aiMaxSec + 5) throw new Error(`Clip is longer than ${c.aiMaxSec} seconds.`);
    const text = String(j.text || '').trim().slice(0, 3500);
    if (!text) throw new Error('No speech was found.');
    const src = String(j.language || 'unknown');
    await env.BUCKET.put('t/' + a.id, JSON.stringify({ src, text, tr: {} }), { httpMetadata: { contentType: 'application/json' }, customMetadata: { expires: a.md.expires } });
    return json({ src, text, credits: pay.left });
  } catch (e) {
    await refund(env, a.code, c.aiT);
    return json({ error: e.message || 'Failed.' }, 502);
  }
}

async function aiDub(request, env, url, c) {
  const a = await aiAuth(request, env, url); if (a.err) return a.err;
  const lang = url.searchParams.get('lang') || '';
  if (!LANGS[lang]) return json({ error: 'Unknown language.' }, 400);
  const tobj = await env.BUCKET.get('t/' + a.id);
  if (!tobj) return json({ error: 'Transcribe first.' }, 409);
  const t = await tobj.json();
  if (t.tr[lang]) return json({ error: 'Already made.' }, 409);
  if (Object.keys(t.tr).length >= 3) return json({ error: 'Up to 3 languages per link.' }, 400);
  const pay = await charge(env, a.code, c.aiL);
  if (!pay.ok) return json({ error: pay.error }, pay.status);
  try {
    let text = t.text;
    if (String(t.src).toLowerCase() !== LANGS[lang].toLowerCase()) {
      const r = await oai(env, 'chat/completions', {
        method: 'POST', headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ model: env.TRANSLATE_MODEL || 'gpt-4o-mini', messages: [
          { role: 'system', content: `You are a translator. Translate the user's text into ${LANGS[lang]}. Keep the meaning, tone and names. Output only the translation.` },
          { role: 'user', content: t.text }] }),
      });
      if (!r.ok) throw new Error(await errMsg(r, 'Translation failed.'));
      const j = await r.json();
      text = String(j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content || '').trim();
      if (!text) throw new Error('Translation came back empty.');
    }
    const model = env.TTS_MODEL || 'gpt-4o-mini-tts';
    const payload = { model, voice: env.TTS_VOICE || 'alloy', input: text.slice(0, 3500), response_format: 'mp3' };
    if (model.includes('gpt-4o')) payload.instructions = `Speak naturally and clearly in ${LANGS[lang]}.`;
    const sp = await oai(env, 'audio/speech', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(payload) });
    if (!sp.ok) throw new Error(await errMsg(sp, 'Voice generation failed.'));
    await env.BUCKET.put(`v/${a.id}.${lang}`, await sp.arrayBuffer(), { httpMetadata: { contentType: 'audio/mpeg' }, customMetadata: { expires: a.md.expires } });
    t.tr[lang] = text;
    await env.BUCKET.put('t/' + a.id, JSON.stringify(t), { httpMetadata: { contentType: 'application/json' }, customMetadata: { expires: a.md.expires } });
    return json({ lang, text, credits: pay.left });
  } catch (e) {
    await refund(env, a.code, c.aiL);
    return json({ error: e.message || 'Failed.' }, 502);
  }
}

// ---------- AI voice changer (licensed stock voices you choose, Pro only) ----------
function voicesList(env) {
  try {
    const v = JSON.parse(env.AI_VOICES || '[]');
    if (!Array.isArray(v)) return [];
    return v.filter(x => x && typeof x.id === 'string' && /^[A-Za-z0-9]{6,40}$/.test(x.id) && x.name)
      .slice(0, 8).map(x => ({ id: x.id, name: String(x.name).slice(0, 24), emoji: String(x.emoji || '🎤').slice(0, 4) }));
  } catch (e) { return []; }
}
function wavSeconds(ab) {
  if (ab.byteLength < 45) return null;
  const v = new DataView(ab);
  const tag = (o, t) => [...t].every((ch, i) => v.getUint8(o + i) === ch.charCodeAt(0));
  if (!tag(0, 'RIFF') || !tag(8, 'WAVE')) return null;
  const rate = v.getUint32(28, true);
  return rate ? (ab.byteLength - 44) / rate : null;
}
async function aiVoice(request, env, url, c) {
  const a = await aiAuth(request, env, url, 'ELEVENLABS_API_KEY'); if (a.err) return a.err;
  const voices = voicesList(env);
  const idx = Number(url.searchParams.get('voice'));
  if (!Number.isInteger(idx) || idx < 0 || idx >= voices.length) return json({ error: 'Unknown voice.' }, 400);
  if (a.md.aivoice === '1') return json({ error: 'Voice already changed.' }, 409);
  const pay = await charge(env, a.code, c.aiV);
  if (!pay.ok) return json({ error: pay.error }, pay.status);
  try {
    const obj = await env.BUCKET.get('a/' + a.id);
    if (!obj) throw new Error('Audio not found.');
    const ab = await new Response(obj.body).arrayBuffer();
    const secs = wavSeconds(ab);
    if (secs === null) throw new Error('Please use the app to prepare the audio first.');
    if (secs > c.aiMaxSec + 3) throw new Error(`Clip is longer than ${c.aiMaxSec} seconds.`);
    const fd = new FormData();
    fd.append('audio', new Blob([ab], { type: 'audio/wav' }), 'audio.wav');
    fd.append('model_id', env.STS_MODEL || 'eleven_multilingual_sts_v2');
    const r = await fetch(`https://api.elevenlabs.io/v1/speech-to-speech/${encodeURIComponent(voices[idx].id)}?output_format=mp3_44100_128`, {
      method: 'POST', headers: { 'xi-api-key': env.ELEVENLABS_API_KEY }, body: fd });
    if (!r.ok) {
      const j = await r.json().catch(() => ({})); const d = j.detail;
      throw new Error((d && (d.message || (typeof d === 'string' ? d : ''))) || 'Voice change failed.');
    }
    await env.BUCKET.put('a/' + a.id, await r.arrayBuffer(), { httpMetadata: { contentType: 'audio/mpeg' }, customMetadata: { ...a.md, aivoice: '1' } });
    return json({ credits: pay.left, voice: voices[idx].name });
  } catch (e) {
    await refund(env, a.code, c.aiV);
    return json({ error: e.message || 'Failed.' }, 502);
  }
}

// ---------- Cleanup (runs daily by cron) ----------
async function cleanup(env) {
  const now = Date.now();
  for (const prefix of ['a/', 't/', 'v/']) {
  let cursor, loops = 0;
  do {
    const l = await env.BUCKET.list({ prefix, limit: 1000, cursor, include: ['customMetadata'] });
    const dead = l.objects.filter(o => {
      const e = o.customMetadata && o.customMetadata.expires;
      return (e ? Date.parse(e) : o.uploaded.getTime() + 90 * 864e5) < now;
    }).map(o => o.key);
    if (dead.length) await env.BUCKET.delete(dead);
    cursor = l.truncated ? l.cursor : undefined;
  } while (cursor && ++loops < 20);
  }
}

let ogBytes = null;

export default {
  async fetch(request, env) {
    const url = new URL(request.url), path = url.pathname, c = cfg(env);

    if (request.method === 'GET' && path === '/') return html(uploadPage(env, c));
    if (request.method === 'GET' && path === '/og.png') {
      ogBytes = ogBytes || Uint8Array.from(atob(OG_PNG), ch => ch.charCodeAt(0));
      return new Response(ogBytes, { headers: { 'content-type': 'image/png', 'cache-control': 'public, max-age=604800' } });
    }
    if (request.method === 'POST' && path === '/api/upload') return upload(request, env, url, c);
    if (request.method === 'POST' && path === '/api/ai/transcribe') return aiTranscribe(request, env, url, c);
    if (request.method === 'POST' && path === '/api/ai/dub') return aiDub(request, env, url, c);
    if (request.method === 'POST' && path === '/api/ai/voice') return aiVoice(request, env, url, c);

    if (request.method === 'GET' && path === '/manifest.webmanifest') {
      return new Response(JSON.stringify({ name: 'Voicy', short_name: 'Voicy', start_url: '/', scope: '/', display: 'standalone', background_color: '#000000', theme_color: '#000000',
        share_target: { action: '/share-target', method: 'POST', enctype: 'multipart/form-data',
          params: { title: 'title', text: 'text', files: [{ name: 'audio', accept: ['audio/*', 'video/mp4', '.m4a', '.mp3', '.wav', '.ogg', '.opus', '.aac'] }] } },
        icons: [{ src: '/icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any maskable' }, { src: '/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any maskable' }] }),
        { headers: { 'content-type': 'application/manifest+json', 'cache-control': 'public, max-age=86400' } });
    }
    if (request.method === 'POST' && path === '/share-target') return new Response(null, { status: 303, headers: { location: '/?shared=missing' } });
    if (request.method === 'GET' && path === '/sw.js') return new Response(SW, { headers: { 'content-type': 'text/javascript', 'cache-control': 'no-cache' } });
    const ic = path.match(/^\/icon-(192|512)\.png$/);
    if (request.method === 'GET' && ic) return new Response(b64bytes(ICONS[ic[1]]), { headers: { 'content-type': 'image/png', 'cache-control': 'public, max-age=604800' } });

    const mv = path.match(/^\/v\/([a-z0-9]{8})\.([a-z]{2})$/);
    if (request.method === 'GET' && mv && LANGS[mv[2]]) return serveAudio(request, env, `v/${mv[1]}.${mv[2]}`);

    if (request.method === 'GET' && path === '/api/credits') {
      const code = (request.headers.get('x-pro-code') || '').trim().toUpperCase();
      const raw = code && env.DATA ? await env.DATA.get('c:' + code) : null;
      if (!raw) return json({ error: 'not found' }, 404);
      return json({ credits: JSON.parse(raw).credits });
    }
    if (request.method === 'GET' && path === '/redeem') return redeem(url, env, c);

    const cardM = path.match(/^\/a\/([a-z0-9]{8})\.png$/);
    if (request.method === 'GET' && cardM) {
      const cm = await env.BUCKET.head('a/' + cardM[1]);
      if (!cm || isExpired(cm.customMetadata)) return new Response('Not found', { status: 404 });
      const md0 = cm.customMetadata || {};
      return new Response(renderCard(md0.wf, Number(md0.dur) || 0), { headers: { 'content-type': 'image/png', 'cache-control': 'public, max-age=86400' } });
    }

    const m = path.match(/^\/(a|f)\/([a-z0-9]{8})$/);
    if (m && request.method === 'GET') {
      if (m[1] === 'f') return serveAudio(request, env, 'a/' + m[2]);
      const meta = await env.BUCKET.head('a/' + m[2]);
      if (!meta || isExpired(meta.customMetadata)) return html(msgPage('🫥', 'Link not found', 'This audio may have expired.'), 404);
      const md = meta.customMetadata || {};
      const tobj = await env.BUCKET.get('t/' + m[2]);
      const t = tobj ? await tobj.json() : null;
      return html(playerPage(m[2], { title: md.title, pro: md.pro === '1', aivoice: md.aivoice === '1', wf: md.wf, dur: Number(md.dur) || 0 }, url.origin, env, t), 200, t ? 'public, max-age=15' : 'public, max-age=60');
    }
    return new Response('Not found', { status: 404 });
  },

  async scheduled(event, env, ctx) { ctx.waitUntil(cleanup(env)); },
};
